contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call sequence: optionally fund C via addToBalance, then try withdrawBalance and check postconditions.
    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        // ensure this test contract has enough Ether to send deposit when calling addToBalance
        require(address(this).balance >= deposit);

        // record before values
        uint beforeStored = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;
        uint beforeSelfBal = address(this).balance;

        bool depositReverted;
        // attempt to add deposit to C on behalf of this contract
        c.addToBalance{value: deposit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depositReverted = true;
        } else {
            depositReverted = false;
        }

        // read stored balance after deposit attempt (may be unchanged if deposit reverted)
        uint midStored = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint midContractBal = address(c).balance;

        bool withdrawReverted;
        // attempt withdraw; we capture whether it reverts
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint afterStored = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;
        uint afterSelfBal = address(this).balance;

        // If withdraw did not revert then (1) recorded balance for this test contract is zero
        // and (2) this test contract's Ether balance increased by exactly the amount that was
        // recorded immediately before the withdraw (which is midStored), and C's balance
        // decreased by at least that same amount.
        assert(withdrawReverted || (afterStored == 0 && afterSelfBal == beforeSelfBal - (depositReverted ? 0 : deposit) + midStored && beforeContractBal + (depositReverted ? 0 : deposit) >= afterContractBal + midStored));
    }

    // allow receiving Ether when C sends funds during withdraw
    receive() external payable {}
}

