// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 beforeStored;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeStored = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        uint beforeSelfBal = address(this).balance;
        bool depositReverted;
        try c.addToBalance{value: deposit}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }
        uint256 midStored;
        try c.getBalance(address(this)) returns (uint256 __r) { midStored = __r; } catch { return; }
        uint midContractBal = address(c).balance;
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 afterStored;
        try c.getBalance(address(this)) returns (uint256 __r) { afterStored = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        uint afterSelfBal = address(this).balance;
        assertTrue(withdrawReverted || (afterStored == 0 && afterSelfBal == beforeSelfBal - (depositReverted ? 0 : deposit) + midStored && beforeContractBal + (depositReverted ? 0 : deposit) >= afterContractBal + midStored));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
